import { expect, expectStatus, test } from "../../fixtures";

// Note: the expiry date must come from the uploaded file's content. The upload schema has no
// expiry field, so this test assumes extraction reads "Expiration Date: <today>" from the text.
// If the seed or fixture files use a different format, adjust `certificateText`.
const TODAY = new Date().toISOString().slice(0, 10); // YYYY-MM-DD, 2026-11-11 for the reference run

function uniqueSuffix(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

test.describe("vendor lifecycle", () => {
  test(
    "A certificate that expires today can still be approved",
    { tag: "@LIF-07" },
    async ({ apiAs }) => {
      // Arrange: a vendor in review with an insurance certificate that expires today.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await member.post("/api/vendors", {
        data: {
          name: `LIF-07 Expiry ${uniqueSuffix()}`,
          category: "services",
          contact_email: `lif07-${uniqueSuffix()}@vendors.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(created, 201);

      const certificateText = `ACME Insurance Certificate\nExpiration Date: ${TODAY}\n`;
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "certificate.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(certificateText),
          },
        },
      });
      const document = await expectStatus<{ id: string }>(upload, 201);

      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submittedVendor = await expectStatus<{ status: string }>(submitted, 200);
      expect(submittedVendor.status).toBe("in_review");

      // Extraction may run asynchronously: wait until the document reports "extracted".
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            const body = await expectStatus<{ status: string }>(res, 200);
            return body.status;
          },
          { timeout: 30_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      const extractionRes = await member.get(`/api/documents/${document.id}/extraction`);
      const extraction = await expectStatus<{ id: string; status: string }>(extractionRes, 200);
      expect(extraction.status).toBe("pending_review");

      // Act: the reviewer approves the insurance certificate extraction.
      const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const approved = await expectStatus<{ status: string }>(decision, 200);
      expect(approved.status).toBe("approved");
    },
  );
});
